SELECT data_rows.id, data_rows.should_delete, data_rows.name, data_rows.description, data_rows.created_by_user_id, data_rows.visibility, data_rows.internal, data_rows.conversation_id, data_rows.goal_id, data_rows.agent_ref, data_rows.model_override, data_rows.user_cred_url, data_rows.enabled, data_rows.start_at, data_rows.end_at, data_rows.schedule_type, data_rows.cron_expr, data_rows.interval_seconds, data_rows.timezone, data_rows.timeout_seconds, data_rows.task_prompt_uri, data_rows.task_prompt, data_rows.next_run_at, data_rows.last_run_at, data_rows.last_status, data_rows.last_error, data_rows.lease_owner, data_rows.lease_until, data_rows.created_at, data_rows.updated_at FROM  (SELECT 0 AS should_delete, `id`, `name`, `description`, `created_by_user_id`, `visibility`, `internal`, `conversation_id`, `goal_id`, `agent_ref`, `model_override`, `user_cred_url`, `enabled`, `start_at`, `end_at`, `schedule_type`, `cron_expr`, `interval_seconds`, `timezone`, `timeout_seconds`, `task_prompt_uri`, `task_prompt`, `next_run_at`, `last_run_at`, `last_status`, `last_error`, `lease_owner`, `lease_until`, `created_at`, `updated_at` FROM schedule)  data_rows